WFJ.Data.add("spell", {
  [1227019] = { "Combina tre Fel-Touched Flowers in una pozione che mostra temporaneamente le ombre demoniache.", nil, 0xd8072b95, nil, "um" },
  [1227022] = { "Permette a chi lo usa di vedere temporaneamente le ombre demoniache nel ⟦Felwood=Vilbosco⟧.", "Individua temporaneamente gli spettri demoniaci.", 0xe41c07dc, 0xadfae0b1, "uu" },
  [1227080] = { "Ti insegna a cucinare i banchetti più ambiti di Carrie Hearthfire.", nil, 0x86b738e2, nil, "um" },
  [1227088] = { "Riduce del $N1% il tempo di lancio della tua prossima ⟦Lesser Healing Wave=Ondata di Cura Inferiore⟧, ⟦Healing Wave=Ondata di Cura⟧ o ⟦Chain Heal=Catena di Guarigione⟧.", "Tempo di lancio del tuo prossimo incantesimo ⟦Lesser Healing Wave=Ondata di Cura Inferiore⟧, ⟦Healing Wave=Ondata di Cura⟧ o ⟦Chain Heal=Catena di Guarigione⟧ ridotto del $N1%.", 0x48076aec, 0x818b5786, "uu" },
  [1227093] = { "Le cure del tuo ⟦Earth Shield=Scudo di Terra⟧ hanno il $N1% di probabilità di rendere istantanea la tua prossima cura con tempo di lancio.", nil, 0x33442dfd, nil, "um" },
  [1227099] = { "⟦Healing Wave=Ondata di Cura⟧ e ⟦Lesser Healing Wave=Ondata di Cura Inferiore⟧ curano anche il bersaglio del tuo ⟦Earth Shield=Scudo di Terra⟧ per il $N1% della cura, se si tratta di un bersaglio diverso.", nil, 0x3e304e89, nil, "um" },
  [1227111] = { "La tua ⟦Chain Heal=Catena di Guarigione⟧ raggiunge $N1 bersagli aggiuntivi e la sua efficacia diminuisce del $N2% in meno a ogni salto.", nil, 0x334bd511, nil, "um" },
  [1227153] = { "I tuoi incantesimi Folgore attivano l'abilità runica Maestria nello Scudo, e l'effetto di Maestria nello Scudo ora può cumularsi fino a $N1 volte.", nil, 0xf5d10fd3, nil, "um" },
  [1227159] = { "Ogni volta che il tuo ⟦Lightning Shield=Scudo di Fulmini⟧ infligge danni, ti curi del $N1% dei danni inflitti, non più di una volta ogni $D1.", nil, 0xde3b1bd6, nil, "um" },
  [1227164] = { "I cumuli di Maestria nello Scudo riducono anche il tempo di lancio del tuo ⟦Lava Burst=Getto di Lava⟧ del $N1% per cumulo. ⟦Lava Burst=Getto di Lava⟧ non consuma più le cariche di Arma del Maelstrom.", nil, 0x399b80ae, nil, "um" },
  [1227175] = { "I tuoi colpi critici non periodici da ombra e da fuoco fanno bruciare il bersaglio per il $N1% dei danni inflitti in $D1.", nil, 0x021ac618, nil, "um" },
  [1227177] = { nil, "In fiamme.", nil, 0xfaec4c73, "mu" },
  [1227186] = { "⟦Shadow Bolt=Dardo d'Ombra⟧, Tormento, Dardo del Caos, Fendente d'Ombra e ⟦Soul Fire=Fuoco dell'Anima⟧ infliggono il $N1% di danni in più ai bersagli colpiti dalla tua Corruzione.", nil, 0xfc2d1b7b, nil, "um" },
  [1227196] = { "I tuoi colpi critici periodici forniscono il $N1% di celerità nel lancio degli incantesimi per $D1, e Ritorno di Fiamma fornisce un ulteriore $N3% di celerità nel lancio degli incantesimi.", nil, 0x88956523, nil, "um" },
  [1227200] = { nil, "Celerità nel lancio degli incantesimi aumentata del $N1%.", nil, 0x0f60ce95, "mu" },
  [1227204] = { "Ti curi del $N1% di tutti i danni inflitti dalla tua Corruzione. Questa cura sale al $N2% se il bersaglio è colpito anche dal tuo ⟦Drain Life=Risucchio di Vita⟧.", nil, 0xe500dc4e, nil, "um" },
  [1227214] = { "Il tuo Fendente d'Ombra ora applica la tua Corruzione (Grado $N1) a ogni bersaglio colpito, ma la sua durata è di soli $D1.", nil, 0x0fb8057d, nil, "um" },
  [1227228] = { "La tua Armatura Infernale ora aumenta anche del $N1% tutti i danni magici che infliggi e dura $D1 in più.", nil, 0xa83b1029, nil, "um" },
  [1227231] = { "I danni di ⟦Heroic Strike=Assalto Eroico⟧, Fendente e Assalto Lampo aumentano del $N1% in ⟦Battle Stance=Postura da Battaglia⟧ o in ⟦Berserker Stance=Postura da Berserker⟧. Fendente colpisce $N2 bersaglio aggiuntivo e può attivare Impeto di Sangue.", nil, 0x085c450e, nil, "um" },
  [1227232] = { "Ogni volta che colpisci un bersaglio con Turbine, ⟦Heroic Strike=Assalto Eroico⟧, Assalto Lampo o Fendente, i danni della tua prossima Contusione aumentano del $N1%, cumulabili fino a $N2 volte.", nil, 0x6e0b8c34, nil, "um" },
  [1227234] = { "Ogni volta che ⟦Deep Wounds=Ferite Profonde⟧ infligge danni, riduce di $D1 il tempo di recupero rimanente del tuo Turbine. Turbine infligge il $N2% di danni in più ai bersagli colpiti dalle tue ⟦Deep Wounds=Ferite Profonde⟧.", nil, 0x81685309, nil, "um" },
  [1227237] = { "La tua Onda d'Urto infligge il $N1% di danni in più e il suo tempo di recupero si riduce di $D1 ogni volta che colpisci un bersaglio con ⟦Heroic Strike=Assalto Eroico⟧ o Fendente.", nil, 0x8f2389fc, nil, "um" },
  [1227242] = { "Avventatezza, Rappresaglia e ⟦Shield Wall=Muro di Scudi⟧ non condividono più il tempo di recupero. Inoltre, Avventatezza dura $D1 in più e, mentre è attiva, ottieni come Forza il $N2% della tua Difesa oltre $N3.", nil, 0x4b0f569f, nil, "um" },
  [1227245] = { "Le tue abilità non richiedono più una postura. Inoltre, i colpi di Rivincita, Sfondamento o ⟦Shield Slam=Colpo di Scudo⟧ aumentano del $N1% i danni del tuo prossimo Turbine o della tua prossima Esecuzione, cumulabili fino a $N2 volte.", nil, 0x00b0d496, nil, "um" },
  [1227343] = { "Ti concede l'accesso permanente alla taverna di New Avalon senza bisogno di portare con te una Tessera di Socio del Circolo Esclusivo.\n\nPer entrare devi comunque indossare un travestimento.", nil, 0xa3d914eb, nil, "um" },
  [1227358] = { "Stordito brevemente dalla tua stessa inettitudine.", "Stordito brevemente dalla tua stessa inettitudine.", 0x68bfe0fb, 0x68bfe0fb, "uu" },
